<?php
namespace App\Http\Controllers\Api;
use App\Http\Requests\EnterpriseRequest; use App\Http\Requests\MasterIndexRequest; use App\Http\Resources\DepartmentResource; use App\Models\Department; use App\Repositories\EnterpriseRepository; use App\Services\EnterpriseService;
class DepartmentController extends BaseApiController { private EnterpriseService $service; public function __construct(){ $this->service=new EnterpriseService(new EnterpriseRepository(new Department)); } public function index(MasterIndexRequest $r){$this->authorize('viewAny',Department::class);return $this->respondWithResource(DepartmentResource::collection($this->service->paginate($r->validated())),'Departments retrieved successfully.');} public function store(EnterpriseRequest $r){return $this->respondSuccess(new DepartmentResource($this->service->create($r->validated())),'Department created successfully.',201);} public function show(Department $department){return $this->respondSuccess(new DepartmentResource($department));} public function update(EnterpriseRequest $r,Department $department){return $this->respondSuccess(new DepartmentResource($this->service->update($department,$r->validated())),'Department updated successfully.');} public function destroy(Department $department){$this->service->delete($department);return $this->respondSuccess(null,'Department deleted successfully.');} }
